/*! zhtml v2.0.0 - Unlicensed - inspired by alpinejs */

var zhtml = window.zhtml || (() => {
  const typing = () =>
    document.activeElement?.matches("input, textarea, select, [contenteditable]");

  // Only changes from defaults are stored: fields that are added
  // later (eg. a new calendar's checkbox) keep the defaults instead of
  // falling back to a snapshot that they're not in.

  const persist = (form) => {
    const key = form.getAttribute("z-persist") || `@ui/form/${form.id}`;
    const fields = () => [...form.elements].filter(el => el.name);
    const field_key = (el) => el.type == "checkbox" ? `${el.name}=${el.value}` : el.name;

    const restore = () => {
      let saved;
      try { saved = JSON.parse(localStorage.getItem(key)) || {}; }
      catch { saved = {}; }

      for(const el of fields()) {
        if(!(field_key(el) in saved)) continue;
        if(el.type == "checkbox") el.checked = saved[field_key(el)];
        else el.value = saved[field_key(el)];
      }
    };

    const save = () => {
      const diff = {};
      for(const el of fields()) {
        if(el.type == "checkbox") {
          if(el.checked != el.defaultChecked) diff[field_key(el)] = el.checked;
        }
        else if(el.value != el.defaultValue) diff[field_key(el)] = el.value;
      }
      localStorage.setItem(key, JSON.stringify(diff));
    };

    form.addEventListener("change", save);
    restore();
  };

  // Keyboard shortcuts: pressing one of the (space-separated) keys in
  // z-key clicks the element. Keys look like "e", "escape" or
  // "mod+enter", where "mod" means ctrl or cmd.
  //
  // An element only responds while its scope holds focus: the closest
  // ancestor carrying a tabindex, or the whole document if there is
  // none. Plain keys are ignored while typing in a field; modified keys
  // and escape always fire.

  const hotkeys = new Set();

  const pressed = (node, e) => {
    const mod = e.ctrlKey || e.metaKey;
    return node.getAttribute("z-key").toLowerCase().split(/\s+/).some((combo) => {
      const parts = combo.split("+");
      const key = parts.pop();
      return key == e.key.toLowerCase() && mod == parts.includes("mod") && !e.altKey;
    });
  };

  const scope_of = (node) =>
    node.parentElement?.closest("[tabindex]") || document.documentElement;

  document.addEventListener("keydown", (e) => {
    if(typing() && !e.ctrlKey && !e.metaKey && e.key != "Escape") return;

    for(const node of hotkeys) if(!node.isConnected) hotkeys.delete(node);

    const focus = document.activeElement ?? document.body;
    const found = [...hotkeys].filter((node) =>
      pressed(node, e) && scope_of(node).contains(focus));

    // Prefer a scoped match (eg. inside the focused list item) over a
    // document-wide one.
    const node = found.find((n) => scope_of(n) != document.documentElement) ?? found[0];

    if(node) {
      e.preventDefault();
      e.stopPropagation();
      if(node.matches("input[type=search], input[type=text], textarea, select, [contenteditable]")) {
        node.focus();
        node.select?.();
      }
      else node.click();
    }
  }, true);

  const directives = {
    "z-toggle": (node, selector) => {
      const targets = () => document.querySelectorAll(selector);

      if(node.matches("input[type=checkbox]")) {
        const sync = () => targets().forEach(t => t.hidden = !node.checked);
        node.addEventListener("change", sync);
        sync();
      }
      else node.addEventListener("click", () =>
        targets().forEach(t => t.hidden = !t.hidden));
    },

    "z-dismiss": (node, trigger) => {
      if(trigger != "escape") return;
      document.addEventListener("keydown", (e) => {
        if(e.key == "Escape" && node.isConnected) node.hidden = true;
      });
    },

    "z-confirm": (node, message) => {
      node.addEventListener("click", (e) => {
        if(!confirm(message)) {
          e.preventDefault();
          e.stopImmediatePropagation();
        }
      });
    },

    "z-persist": (node) => persist(node),

    "z-var": (node, property) => {
      const unit = node.getAttribute("z-unit") || "";
      const sync = () => document.documentElement.style.setProperty(property, node.value + unit);
      node.addEventListener("input", sync);
      sync();
    },

    "z-key": (node) => hotkeys.add(node),

    // Clicking writes the element's value into the field matching the
    // selector and fires input + change, as if the user typed it.
    "z-set": (node, selector) => node.addEventListener("click", () => {
      const target = document.querySelector(selector);
      target.value = node.value;
      target.dispatchEvent(new Event("input", { bubbles: true }));
      target.dispatchEvent(new Event("change", { bubbles: true }));
    }),

    // Arrow keys move focus through the elements matching the selector,
    // in document order.
    "z-nav": (node, selector) => document.addEventListener("keydown", (e) => {
      if(e.key != "ArrowDown" && e.key != "ArrowUp") return;

      const items = [...node.querySelectorAll(selector)];
      const idx = items.indexOf(document.activeElement);
      if(idx == -1 && typing()) return;

      e.preventDefault();
      (items[idx + (e.key == "ArrowDown" ? 1 : -1)] ?? items[idx] ?? items[0])?.focus();
    }),

    // Ask before discarding a form with unsaved edits. Any input marks
    // the form dirty; capture-phase so the question comes before other
    // click handlers act on the element.
    "z-discard": (node, message) => {
      const form = node.closest("form");
      form?.addEventListener("input", () => form.z_dirty = true);

      node.addEventListener("click", (e) => {
        if(form?.z_dirty && !confirm(message)) {
          e.preventDefault();
          e.stopImmediatePropagation();
        }
      }, true);
    },

    // Repeatable form rows: [data-add] clones the row template into
    // .repeat__rows, [data-remove] drops its .repeat__row. Rows count as
    // form edits. The attribute value, if any, is the confirmation asked
    // before removing a row whose [data-value] field holds something.
    "z-repeat": (node, message) => node.addEventListener("click", (e) => {
      const edited = () => node.dispatchEvent(new Event("input", { bubbles: true }));

      if(e.target.closest("[data-add]")) {
        node.querySelector(".repeat__rows")
          .append(node.querySelector("template").content.cloneNode(true));
        edited();
      }

      const remove = e.target.closest("[data-remove]");
      if(remove) {
        const row = remove.closest(".repeat__row");
        if(message && row.querySelector("[data-value]")?.value.trim() && !confirm(message)) return;
        row.remove();
        edited();
      }
    }),
  };

  const selector = () => Object.keys(directives).map(name => `[${name}]`).join(", ");

  const bind = (node) => {
    node.z_bound ??= new Set();

    for(const [name, apply] of Object.entries(directives))
      if(node.hasAttribute(name) && !node.z_bound.has(name)) {
        node.z_bound.add(name);
        apply(node, node.getAttribute(name));
      }
  };

  const hydrate = (root) => {
    if(root.matches?.(selector())) bind(root);
    root.querySelectorAll?.(selector()).forEach(bind);
  };

  // Registers a custom directive; apps use this for behaviour too
  // specific for the library itself.
  const directive = (name, apply) => {
    directives[name] = apply;
    if(document.readyState != "loading") hydrate(document.body);
  };

  addEventListener("DOMContentLoaded", () => {
    hydrate(document.body);

    new MutationObserver((mutations) => {
      for(const mutation of mutations)
        for(const node of mutation.addedNodes)
          if(node.nodeType == 1) hydrate(node);
    }).observe(document.documentElement, { childList: true, subtree: true });
  });

  return { directive, hydrate };
})();
